import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { scenePosition, cinematicPrimitives } = config;
  const geometry = new THREE.PlaneGeometry(1.6, 1);
  const texture = ctx.textureLoader.load(config.imageUrl);
  const material = new THREE.MeshBasicNodeMaterial({ map: texture, transparent: true });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  mesh.rotation.set(scenePosition.rotation?.x || 0, scenePosition.rotation?.y || 0, scenePosition.rotation?.z || 0);
  mesh.scale.set(scenePosition.scale?.x || 1, scenePosition.scale?.y || 1, scenePosition.scale?.z || 1);

  const origY = mesh.position.y;
  let hoverTween, pressTween;

  const handlers = {
    pointerenter: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, { y: origY + 0.15, duration: 0.7, ease: 'power3.out' });
    },
    pointerleave: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, { y: origY, duration: 0.5, ease: 'power2.out' });
    },
    pointerdown: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(mesh.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    },
    pointerup: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(mesh.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
    },
    click: () => {
      if (ctx.emit) ctx.emit('navigate', { to: 'hub-journal.select' });
    }
  };
  mesh.userData.handlers = handlers;

  // Apply cinematic primitives
  if (cinematicPrimitives && cinematicPrimitives.length) {
    cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](mesh, primitive.params);
      }
    });
  }

  // Mark as interactive for raycasting
  mesh.userData.interactive = true;

  // Cleanup
  mesh.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  return mesh;
}
